  'intro-p3-text': { en:'Get a PDF ready to print and sign.', nl:'Je krijgt een PDF die je kunt printen en ondertekenen.', es:'Obtén un PDF listo para imprimir y firmar.', fr:'Obtenez un PDF prêt à imprimer et à signer.', de:'Sie erhalten ein PDF, das Sie ausdrucken und unterschreiben können.', pt:'Get a PDF ready to print and sign.', it:'Get a PDF ready to print and sign.', ru:'Get a PDF ready to print and sign.', zh:'获取可打印和签署的PDF。', ja:'印刷・署名用のPDFを取得。', ar:'احصل على PDF جاهز للطباعة والتوقيع.', ko:'인쇄 및 서명이 가능한 PDF를 받으세요.', tr:'Yazdırmaya ve imzalamaya hazır bir PDF alın.', pl:'Pobierz PDF gotowy do wydruku i podpisu.', hi:'प्रिंट और हस्ताक्षर के लिए PDF प्राप्त करें।', fa:'PDF آماده چاپ و امضا دریافت کنید.', he:'קבל PDF מוכן להדפסה וחתימה.', sw:'Pata PDF tayari kuchapishwa na kusainiwa.' },
