  'privacy-link': { en:'Privacy Policy', nl:'Privacybeleid', es:'Política de Privacidad', fr:'Politique de Confidentialité', de:'Datenschutzerklärung', pt:'Privacidade', it:'Privacy', ru:'Конфиденциальность', zh:'隐私政策', ja:'プライバシーポリシー', ar:'سياسة الخصوصية', ko:'개인정보 처리방침', tr:'Gizlilik Politikası', pl:'Polityka prywatności', hi:'गोपनीयता नीति', fa:'حریم خصوصی', he:'מדיניות פרטיות', sw:'Sera ya Faragha' },
  'warn-year': { en:'Enter a year between 1900 and {max}', nl:'Voer een jaar in tussen 1900 en {max}', es:'Introduzca un año entre 1900 y {max}', fr:'Entrez une année entre 1900 et {max}', de:'Geben Sie ein Jahr zwischen 1900 und {max} ein', pt:'Insira um ano entre 1900 e {max}', it:'Inserisci un anno tra il 1900 e il {max}', ru:'Введите год от 1900 до {max}', zh:'请输入1900到{max}之间的年份', ja:'1900年から{max}年の間の年を入力してください', ar:'أدخل سنة بين 1900 و {max}', ko:'1900년에서 {max}년 사이의 연도를 입력하세요', tr:'1900 ile {max} arasında bir yıl girin', pl:'Wpisz rok między 1900 a {max}', hi:'1900 और {max} के बीच का वर्ष दर्ज करें', fa:'سالی بین ۱۹۰۰ و {max} وارد کنید', he:'הזן שנה בין 1900 ל-{max}', sw:'Weka mwaka kati ya 1900 na {max}' },
  'warn-date-range': { en:'End date is before the start date', nl:'Einddatum ligt vóór de startdatum', es:'La fecha de fin es anterior a la de inicio', fr:'La date de fin est antérieure à la date de début', de:'Das Enddatum liegt vor dem Startdatum', pt:'A data final é anterior à data inicial', it:'La data di fine è precedente alla data di inizio', ru:'Дата окончания раньше даты начала', zh:'结束日期早于开始日期', ja:'終了日が開始日より前です', ar:'تاريخ النهاية قبل تاريخ البداية', ko:'종료일이 시작일보다 앞섭니다', tr:'Bitis tarihi baslangic tarihinden once', pl:'Data koncowa jest przed data poczatkowa', hi:'समाप्ति तिथि प्रारंभ तिथि से पहले है', fa:'تاریخ پایان قبل از تاریخ شروع است', he:'תאריך הסיום לפני תאריך ההתחלה', sw:'Tarehe ya mwisho ni kabla ya tarehe ya kuanza' },
  'warn-empty-fields': { en:'Some fields are still empty. You can continue, but the document may be incomplete.', nl:'Sommige velden zijn nog leeg. Je kunt doorgaan, maar het document is mogelijk onvolledig.', es:'Algunos campos están vacíos. Puede continuar, pero el documento podría estar incompleto.', fr:'Certains champs sont encore vides. Vous pouvez continuer, mais le document pourrait être incomplet.', de:'Einige Felder sind noch leer. Sie können fortfahren, aber das Dokument ist möglicherweise unvollständig.', pt:'Alguns campos ainda estão vazios. Você pode continuar, mas o documento pode ficar incompleto.', it:'Alcuni campi sono ancora vuoti. Puoi continuare, ma il documento potrebbe essere incompleto.', ru:'Некоторые поля ещё пусты. Вы можете продолжить, но документ может быть неполным.', zh:'某些字段仍为空。您可以继续但文件可能不完整。', ja:'一部のフィールドが空です。続行できますが書類が不完全な場合があります。', ar:'بعض الحقول فارغة. يمكنك المتابعة لكن المستند قد يكون غير مكتمل.', ko:'일부 필드가 비어 있습니다. 계속할 수 있지만 문서가 불완전할 수 있습니다.', tr:'Bazi alanlar bos. Devam edebilirsiniz ama belge eksik olabilir.', pl:'Niektore pola sa puste. Mozesz kontynuowac ale dokument moze byc niekompletny.', hi:'कुछ फ़ील्ड अभी भी खाली हैं। जारी रख सकते हैं लेकिन दस्तावेज़ अपूर्ण हो सकता है।', fa:'برخی فیلدها خالی است. می‌توانید ادامه دهید ولی سند ناقص باشد.', he:'שדות ריקים. ניתן להמשיך אך המסמך עלול להיות חלקי.', sw:'Sehemu zingine bado tupu. Unaweza kuendelea lakini hati inaweza kuwa haijakamilika.' },
